def _load_manifest(path: Path = COMPONENTS_FILE) -> Dict[str, Any]:
    """Load and parse manifest with strict error propagation."""
    if not path.exists():
        raise FileNotFoundError(f"Manifest not found: {path}")
    if path.stat().st_size > MAX_MANIFEST_SIZE:
        raise ValueError(f"Manifest exceeds size limit: {path.stat().st_size} bytes")
    with open(path, "r", encoding="utf-8") as f:
        data = json.load(f)
    if not isinstance(data, dict):
        raise TypeError("Manifest root must be a JSON object")
    return data


def _get_components(manifest: Dict[str, Any]) -> List[Dict[str, Any]]:
    """Extract component list with validation."""
    comps = manifest.get("components")
    if not isinstance(comps, list):
        raise TypeError("'components' must be a list")
    return comps


def _validate_semver(version: str) -> bool:
    """Strict semver 2.0.0 validation (MAJOR.MINOR.PATCH[-prerelease][+build])."""
    import re
    pattern = r"^(0|[1-9]\d*)\.(0|[1-9]\d*)\.(0|[1-9]\d*)(?:-((?:0|[1-9]\d*|\d*[a-zA-Z-][0-9a-zA-Z-]*)(?:\.(?:0|[1-9]\d*|\d*[a-zA-Z-][0-9a-zA-Z-]*))*))?(?:\+([0-9a-zA-Z-]+(?:\.[0-9a-zA-Z-]+)*))?$"
    return bool(re.match(pattern, version))


def _validate_dependency(dep: Any, known_names: Set[str]) -> Tuple[bool, str]:
    """Validate a single dependency entry. Returns (valid, error_msg)."""
    if isinstance(dep, str):
        if dep not in known_names:
            return False, f"Dependency '{dep}' not in known components"
        return True, ""
    if isinstance(dep, dict):
        name = dep.get("name")
        if not isinstance(name, str) or name not in known_names:
            return False, f"Invalid dependency name: {name}"
        version = dep.get("version")
        if version is not None and not _validate_semver(str(version)):
            return False, f"Invalid semver for dependency '{name}': {version}"
        return True, ""
    return False, f"Invalid dependency type: {type(dep).__name__}"


