    def test_component_types_are_valid(self, components):
        valid_types = {"service", "worker", "database", "cache", "queue", "gateway", "utility"}
        for comp in components:
            ctype = comp.get("type")
            assert ctype in valid_types, f"Invalid type '{ctype}' for {comp.get('name')}"

    def test_component_versions_are_semver(self, components):
        for comp in components:
            version = comp.get("version")
            assert _validate_semver(str(version)), f"Invalid semver '{version}' for {comp.get('name')}"

    def test_dependencies_reference_existing_components(self, components):
        names = {c["name"] for c in components}
        for comp in components:
            for dep in comp.get("dependencies", []):
                valid, err = _validate_dependency(dep, names)
                assert valid, f"{comp['name']}: {err}"

    def test_dependencies_is_list(self, components):
        for comp in components:
            deps = comp.get("dependencies")
            assert isinstance(deps, list), f"dependencies must be list for {comp.get('name')}"

    def test_metadata_is_dict_if_present(self, components):
        for comp in components:
            meta = comp.get("metadata")
            if meta is not None:
                assert isinstance(meta, dict), f"metadata must be dict for {comp.get('name')}"

    def test_no_orphan_components(self, components):
        """Every component must be referenced by at least one dependency or be a root."""
        names = {c["name"] for c in components}
        referenced = set()
        for comp in components:
            for dep in comp.get("dependencies", []):
                if isinstance(dep, str):
                    referenced.add(dep)
                elif isinstance(dep, dict):
                    referenced.add(dep.get("name"))
        orphans = names - referenced
        # Allow multiple roots, but log them for visibility
        if orphans:
            pytest.skip(f"Orphan components (not dependencies of any other): {orphans}")

    def test_dependency_graph_is_acyclic(self, components):
        """Detect cycles in the dependency graph via DFS."""
        names = {c["name"] for c in components}
        adj: Dict[str, Set[str]] = {n: set() for n in names}
        for comp in components:
            for dep in comp.get("dependencies", []):
                dep_name = dep if isinstance(dep, str) else dep.get("name")
                if dep_name in adj:
                    adj[comp["name"]].add(dep_name)

        WHITE, GRAY, BLACK = 0, 1, 2
        color = {n: WHITE for n in names}

        def dfs(node: str, path: List[str]) -> bool:
            color[node] = GRAY
            path.append(node)
            for neighbor in adj[node]:
                if color[neighbor] == GRAY:
                    cycle = path[path.index(neighbor):] + [neighbor]
                    raise AssertionError(f"Dependency cycle detected: {' -> '.join(cycle)}")
                if color[neighbor] == WHITE:
                    dfs(neighbor, path)
            path.pop()
            color[node] = BLACK
            return True

        for node in names:
            if color[node] == WHITE:
                dfs(node, [])

