@pytest.mark.stateful
class ManifestStateMachine(RuleBasedStateMachine):
    """Stateful model: track components and validate invariants after each mutation."""

    def __init__(self):
        super().__init__()
        self.components: List[Dict[str, Any]] = []
        self.names: Set[str] = set()

    @rule(name=st.text(min_size=1, max_size=20), version=st.text(min_size=1, max_size=20))
    def add_component(self, name: str, version: str):
        """Add a component; duplicate names must be rejected."""
        if name in self.names:
            with pytest.raises(AssertionError):
                assert name not in self.names
        else:
            self.components.append({
                "name": name,
                "type": "service",
                "version": version,
                "dependencies": []
            })
            self.names.add(name)

    @rule(name=st.text(min_size=1, max_size=20))
    def remove_component(self, name: str):
        """Remove a component; must not break references."""
        self.components = [c for c in self.components if c["name"] != name]
        self.names.discard(name)

    @invariant()
    def names_are_unique(self):
        assert len(self.names) == len({c["name"] for c in self.components})

    @invariant()
    def all_dependencies_resolve(self):
        for comp in self.components:
            for dep in comp.get("dependencies", []):
                assert dep in self.names, f"Unresolved dependency: {dep}"


TestManifestStateMachine = ManifestStateMachine.TestCase


