@pytest.mark.performance
class TestPerformance:
    """Performance characteristics of manifest processing."""

    def test_large_manifest_processing_time(self):
        """Simulate a large manifest (10k components) and measure processing."""
        import random
        import string

        def random_name():
            return ''.join(random.choices(string.ascii_lowercase, k=10))

        large_manifest = {
            "components": [
                {
                    "name": f"comp_{i}",
                    "type": "service",
                    "version": "1.0.0",
                    "dependencies": [random_name() for _ in range(random.randint(0, 5))]
                }
                for i in range(10000)
            ]
        }

        start = time.perf_counter()
        names = {c["name"] for c in large_manifest["components"]}
        for comp in large_manifest["components"]:
            for dep in comp["dependencies"]:
                # Simulate validation
                _ = dep in names
        elapsed = time.perf_counter() - start
        assert elapsed < 5.0, f"Large manifest processing took {elapsed:.3f}s (limit 5s)"

    def test_memory_footprint(self):
        """Ensure manifest loading doesn't blow up memory (sanity check)."""
        import tracemalloc
        tracemalloc.start()
        _load_manifest()
        current, peak = tracemalloc.get_traced_memory()
        tracemalloc.stop()
        assert peak < 100 * 1024 * 1024, f"Peak memory usage too high: {peak / 1e6:.1f} MB"


